<?php
namespace App\Domain\PdfProcessing\Services;
use App\Models\{CompressionProfile,DocumentFile,FileIntegrityCheck,ProcessingRun};use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use RuntimeException;
class PreservationProcessor{public function __construct(private PdfCommandRunner $runner){}public function process(DocumentFile $master,CompressionProfile $profile):array{$disk=Storage::disk($master->storage_disk);$input=$disk->path($master->storage_key);if(!is_file($input))throw new RuntimeException('Archival master is missing from private storage.');$tmpRoot=config('pdf_processing.temp_path').'/'.Str::ulid();if(!mkdir($tmpRoot,0700,true)&&!is_dir($tmpRoot))throw new RuntimeException('Cannot create protected processing workspace.');$optimized=$tmpRoot.'/optimized.pdf';$preview=$tmpRoot.'/preview.pdf';$run=ProcessingRun::create(['document_file_id'=>$master->id,'process_type'=>'DERIVATIVE_GENERATION','compression_profile_id'=>$profile->id,'profile_version'=>$profile->version,'attempt'=>1,'worker_name'=>gethostname()?:null,'processor'=>'qpdf + Ghostscript + Poppler','started_at'=>now(),'status'=>'RUNNING','input_sha256'=>$master->sha256,'input_size'=>$master->size_bytes]);try{$this->runner->run([config('pdf_processing.qpdf_binary'),'--check',$input],120);$before=$this->pages($input);$this->runner->run($this->ghostscriptCommand($input,$optimized,$profile));$this->runner->run([config('pdf_processing.qpdf_binary'),'--linearize',$optimized,$preview],300);$after=$this->pages($optimized);if($before!==null&&$after!==null&&$before!==$after)throw new RuntimeException('PAGE_COUNT_MISMATCH');$opt=$this->storeDerivative($master,$optimized,'OPTIMIZED',$profile);$pre=$this->storeDerivative($master,$preview,'PREVIEW',$profile);$ratio=$master->size_bytes>0?round((1-($opt->size_bytes/$master->size_bytes))*100,4):0;$run->update(['finished_at'=>now(),'status'=>'SUCCESS','output_sha256'=>$opt->sha256,'output_size'=>$opt->size_bytes,'compression_ratio'=>$ratio]);return ['optimized'=>$opt,'preview'=>$pre,'compression_ratio'=>$ratio];}catch(\Throwable $e){$run->update(['finished_at'=>now(),'status'=>'FAILED','error_code'=>$this->code($e),'error_message'=>Str::limit($e->getMessage(),5000)]);throw $e;}finally{$this->cleanup($tmpRoot);}}private function ghostscriptCommand(string $input,string $output,CompressionProfile $p):array{$cmd=[config('pdf_processing.ghostscript_binary'),'-dSAFER','-dBATCH','-dNOPAUSE','-sDEVICE=pdfwrite','-dCompatibilityLevel=1.7','-dDetectDuplicateImages=true','-dCompressFonts=true','-dSubsetFonts=true'];if($p->downsampling_allowed){$dpi=(string)($p->target_dpi??300);$cmd=array_merge($cmd,['-dDownsampleColorImages=true','-dColorImageResolution='.$dpi,'-dDownsampleGrayImages=true','-dGrayImageResolution='.$dpi,'-dDownsampleMonoImages=true','-dMonoImageResolution='.$dpi]);}else{$cmd[]='-dDownsampleColorImages=false';$cmd[]='-dDownsampleGrayImages=false';$cmd[]='-dDownsampleMonoImages=false';}if($p->color_mode==='GRAY')$cmd[]='-sColorConversionStrategy=Gray';$cmd[]='-sOutputFile='.$output;$cmd[]=$input;return $cmd;}private function pages(string $path):?int{$out=$this->runner->run([config('pdf_processing.pdfinfo_binary'),$path],60);return preg_match('/^Pages:\s+(\d+)/mi',$out,$m)?(int)$m[1]:null;}private function storeDerivative(DocumentFile $master,string $source,string $role,CompressionProfile $profile):DocumentFile{$version=$master->version;$stored=Str::lower((string)Str::ulid()).'.pdf';$key=preg_replace('#/master/[^/]+$#','/'.strtolower($role).'/'.$stored,$master->storage_key);$stream=fopen($source,'rb');Storage::disk($master->storage_disk)->writeStream($key,$stream);if(is_resource($stream))fclose($stream);$absolute=Storage::disk($master->storage_disk)->path($key);$sha=hash_file('sha256',$absolute);$file=DocumentFile::updateOrCreate(['document_version_id'=>$version->id,'file_role'=>$role],['storage_disk'=>$master->storage_disk,'storage_key'=>$key,'original_filename'=>$master->original_filename,'stored_filename'=>$stored,'mime_type'=>'application/pdf','size_bytes'=>filesize($absolute),'page_count'=>$this->pages($absolute),'sha256'=>$sha,'processing_status'=>'READY','uploaded_by'=>$master->uploaded_by,'uploaded_at'=>now(),'processed_at'=>now()]);FileIntegrityCheck::create(['document_file_id'=>$file->id,'expected_sha256'=>$sha,'calculated_sha256'=>hash_file('sha256',$absolute),'result'=>'PASS','checked_by_type'=>'PROCESSING','checked_at'=>now()]);return $file;}private function cleanup(string $dir):void{if(!is_dir($dir))return;foreach(scandir($dir)?:[] as $f)if(!in_array($f,['.','..'],true))@unlink($dir.'/'.$f);@rmdir($dir);}private function code(\Throwable $e):string{return str_contains($e->getMessage(),'PAGE_COUNT_MISMATCH')?'PAGE_COUNT_MISMATCH':'PROCESSING_FAILED';}}
